ee:message.ee:set-payload:
%dw 2.0
output application/json

var xmlString = write(
  {
    ServiceOfferResponse @("xmlns:xsd": "http://www.w3.org/2001/XMLSchema", "xmlns:xsi": "http://www.w3.org/2001/XMLSchema-instance", "Version": "2.15"): {
      Sender: {
        Organization @(Code: vars.sfOfferAcceptPayload.data.payload.Destination_Organization_Code__c, Type: vars.sfOfferAcceptPayload.data.payload.Destination_Organization_Type__c): {
          Name: vars.sfOfferAcceptPayload.data.payload.Destination_Organization_Name__c,
          OwnerOrganization @(Code: vars.sfOfferAcceptPayload.data.payload.Destination_OwnerOrganization_Code__c, Type: vars.sfOfferAcceptPayload.data.payload.Destination_OwnerOrganization_Type__c): {
            Name: vars.sfOfferAcceptPayload.data.payload.Destination_OwnerOrganization_Name__c
          }
        }
      },
      Destination: {
        Organization @(Code: vars.sfOfferAcceptPayload.data.payload.Sender_Organization_Code__c, Type: vars.sfOfferAcceptPayload.data.payload.Sender_Organization_Type__c): {
          Name: vars.sfOfferAcceptPayload.data.payload.Sender_Organization_Name__c,
		  OwnerOrganization @(Code: vars.sfOfferAcceptPayload.data.payload.Sender_OwnerOrganization_Code__c, Type:vars.sfOfferAcceptPayload.data.payload.Sender_OwnerOrganization_Type__c): {
            Name: vars.sfOfferAcceptPayload.data.payload.Sender_OwnerOrganization_Name__c
          }
        }
      },
       OfferId: vars.sfOfferAcceptPayload.data.payload.OfferID__c,
      ContractCode: vars.sfOfferAcceptPayload.data.payload.Contract_Code__c,
      Status: {
        Accept: true
      },
      Comments: vars.sfOfferAcceptPayload.data.payload.Comments__c,
      AssignedStaff: {
        Name: null,
        Phone: {
          Number: null,
          Extension: null
        }
      },
      ResponsePerson: {
        Name: vars.sfOfferAcceptPayload.data.payload.Name__c,
        Phone: {
          Number: null,
          Extension: null
        }
      }
    }
  },
  "application/xml"
)

---
{
  RequestItems: [
    {
      RequestData: xmlString,
      RequestSenderType: "Team",
     // RequestSenderId: "20593"
    }
  ]
}

dotnet:execute.dotnet:arguments:
#[{
	req: payload,
	username: p('secure::username'),
	password: p('secure::password')
}]
